"""

import json
import logging
import time
from pathlib import Path

from ..config import SESSIONS_DIR
from ..tools._util import to_json
from ._protocol import make_id

log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Goal decomposition templates
# ---------------------------------------------------------------------------

